import {uid,clone} from './storage.js';
import {icon} from './icons.js';
import {fadeFields,readFades} from './fade-ui.js';
import {$,$$,esc,openForm,field,option,confirmAction,toast} from './ui.js';

export class AmbienceUI {
  constructor(ctx){this.ctx=ctx;this.selectedId=null;}
  selected(){return this.ctx.state().ambiences.find(a=>a.id===this.selectedId)||this.ctx.state().ambiences[0];}
  render(root){
    this.root=root;const state=this.ctx.state(),preset=this.selected();if(preset)this.selectedId=preset.id;
    root.innerHTML=`<div class="library-heading"><div><div class="eyebrow">COMPONHA O SOM DO SEU UNIVERSO</div><h1>Ambientes <span class="count-badge">${state.ambiences.length}</span></h1><p>Combine playlists, loops e música para dar vida a cada lugar.</p></div><button class="btn primary" id="newAmbience">${icon('plus')} Novo ambiente</button></div><div class="soundpad-layout"><aside class="playlist-sidebar"><span class="section-eyebrow">AMBIENTES SALVOS</span>${state.ambiences.map(a=>`<button class="playlist-nav ${a.id===preset?.id?'active':''}" data-ambience-select="${esc(a.id)}">${icon('rain')}<span>${esc(a.name)}</span><small>${a.layers.length}</small></button>`).join('')}<div class="library-info">${icon('info')}<p>O ambiente continua tocando ao navegar e durante o carregamento da próxima trilha.</p></div></aside><section class="soundpad-main">${preset?`<header class="soundpad-head"><div><span class="section-eyebrow">SEU SOUNDPAD</span><h2>${esc(preset.name)}</h2><p>${esc(preset.description||'Crie uma combinação de sons para esta atmosfera.')}</p></div><div class="heading-actions"><button class="icon-btn" id="editAmbience" title="Editar ambiente" aria-label="Editar ambiente">${icon('edit')}</button><button class="icon-btn" id="copyAmbience" title="Duplicar ambiente" aria-label="Duplicar ambiente">${icon('copy')}</button><button class="btn primary" id="playAmbience">${icon('play')} Ativar ambiente</button></div></header><div class="soundpad-status"><span class="status-dot"></span><span id="ambienceStatus">Pronto para tocar</span><small>Alterações salvas automaticamente</small></div>${this.musicPanel(preset,state)}<div class="section-heading ambient-layer-heading"><h3>Camadas do ambiente</h3><div class="heading-actions"><button class="btn outline small" id="addAmbientPlaylist">${icon('list')} Adicionar playlist</button><button class="btn subtle small" id="addAmbienceLayer">${icon('plus')} Arquivo</button></div></div><p class="ambience-example">Uma playlist de conversas + talheres ocasionais + jazz na trilha musical: cada fonte tem seu próprio volume.</p><div class="sound-layer-grid">${preset.layers.map(l=>`<article class="sound-layer-card ${l.enabled===false?'disabled':''}"><header><span class="sound-layer-art">${icon(l.playlistId?(l.shuffle?'shuffle':'list'):l.mode==='random'?'bolt':'rain')}</span><label class="sound-toggle"><input type="checkbox" data-amb-enabled="${esc(l.id)}" aria-label="Ativar ${esc(l.name)}" ${l.enabled!==false?'checked':''}><span></span></label><button class="icon-btn" data-edit-amb-layer="${esc(l.id)}" aria-label="Configurar ${esc(l.name)}">${icon('sliders')}</button></header><h3>${esc(l.name)}</h3><p>${esc(l.playlistId?(state.playlists.find(p=>p.id===l.playlistId)?.name||'Playlist ausente')+' · '+(state.playlists.find(p=>p.id===l.playlistId)?.assetIds.length||0)+' faixas':state.audioAssets.find(a=>a.id===l.assetId)?.name||'Arquivo ausente')}</p><div class="sound-layer-mode"><span>${l.playlistId?(l.shuffle?'PLAYLIST ALEATÓRIA':'PLAYLIST EM ORDEM'):l.mode==='random'?'OCASIONAL':'LOOP CONTÍNUO'}</span><small>${l.mode==='random'?`${l.minInterval}–${l.maxInterval}s`:'∞'}</small></div>${l.playlistId?`<div class="ambient-now"><span data-amb-now="${esc(l.id)}">${l.mode==='random'?'Um som a cada intervalo':'Pronta para tocar'}</span>${l.mode!=='random'?`<button class="icon-btn" data-amb-next="${esc(l.id)}" title="Próxima faixa desta camada" aria-label="Próxima faixa de ${esc(l.name)}">${icon('skip')}</button>`:''}</div>`:''}<div class="sound-layer-volume"><input type="range" data-amb-volume="${esc(l.id)}" min="0" max="100" value="${Math.round(l.volume*100)}" aria-label="Volume ${esc(l.name)}"><output data-amb-value="${esc(l.id)}">${Math.round(l.volume*100)}%</output></div></article>`).join('')||`<button class="sound-layer-empty" id="addFirstAmbLayer">${icon('plus')} Adicione um arquivo ou uma playlist de sons para variar o ambiente.</button>`}</div><div class="section-heading"><h3>Disparos manuais</h3><button class="btn subtle small" id="addAmbiencePad">${icon('plus')} Adicionar efeito</button></div><div class="sound-pad-grid">${preset.pads.map(id=>state.audioAssets.find(a=>a.id===id)).filter(Boolean).map(a=>`<div class="sound-pad-wrap"><button class="sound-pad" data-amb-pad="${esc(a.id)}">${icon(/sino/i.test(a.name)?'bell':'bolt')}<strong>${esc(a.name)}</strong><small>TOCAR UMA VEZ</small></button><button class="pad-remove" data-remove-pad="${esc(a.id)}" aria-label="Retirar ${esc(a.name)} deste ambiente">×</button></div>`).join('')||'<p class="empty-small">Adicione botões para os efeitos que você usa com frequência.</p>'}</div><div class="soundpad-bottom"><button class="btn danger" id="stopAmbience">${icon('stop')} Encerrar ambiente com fade</button><p>Encerra as camadas e a trilha deste ambiente. Sons iniciados separadamente continuam.</p></div>`:`<div class="empty-state">${icon('rain')}<h3>Crie sua primeira atmosfera</h3><p>Adicione os áudios na biblioteca e combine suas camadas aqui.</p></div>`}</section></div>`;
    $('#newAmbience',root).onclick=()=>this.edit();$$('[data-ambience-select]',root).forEach(b=>b.onclick=()=>{this.selectedId=b.dataset.ambienceSelect;this.render(root);});
    if(!preset)return;
    $('#editAmbience',root).onclick=()=>this.edit(preset);$('#copyAmbience',root).onclick=()=>{const copy=clone(preset);copy.id=uid('ambience');copy.name+=' (cópia)';state.ambiences.push(copy);this.selectedId=copy.id;this.ctx.commit();};
    $('#playAmbience',root).onclick=async()=>{try{const bus=this.ctx.engine.ambiences;if(bus.active?.id===preset.id&&!bus.paused)bus.stop();else if(bus.active?.id===preset.id&&bus.paused)await this.ctx.engine.resume();else await bus.apply(preset);}catch(e){toast(e.message,true);}};
    $('#stopAmbience',root).onclick=()=>this.ctx.engine.ambiences.stop();
    $('#addAmbientPlaylist',root).onclick=()=>this.editLayer(preset,null,true);$('#editAmbienceMusic',root).onclick=()=>this.editMusic(preset);
    $('[data-amb-music-volume]',root)?.addEventListener('input',e=>{const volume=Number(e.target.value)/100;preset.music.volume=volume;$('[data-amb-music-value]',root).textContent=e.target.value+'%';const bus=this.ctx.engine.ambiences;if(bus.active?.id===preset.id)bus.setMusicVolume(volume);this.ctx.save();});
    $$('[data-amb-next]',root).forEach(button=>button.onclick=()=>this.ctx.engine.ambiences.sequences.get(button.dataset.ambNext)?.advance());
    $('#addAmbienceLayer',root).onclick=()=>this.editLayer(preset);$('#addFirstAmbLayer',root)?.addEventListener('click',()=>this.editLayer(preset));
    $$('[data-edit-amb-layer]',root).forEach(b=>b.onclick=()=>this.editLayer(preset,preset.layers.find(l=>l.id===b.dataset.editAmbLayer)));
    $$('[data-amb-volume]',root).forEach(input=>input.oninput=()=>{const id=input.dataset.ambVolume,volume=Number(input.value)/100;preset.layers.find(l=>l.id===id).volume=volume;$(`[data-amb-value="${CSS.escape(id)}"]`,root).textContent=input.value+'%';if(this.ctx.engine.ambiences.active?.id===preset.id)this.ctx.engine.ambiences.setVolume(id,volume);this.ctx.save();});
    $$('[data-amb-enabled]',root).forEach(input=>input.onchange=async()=>{const layer=preset.layers.find(l=>l.id===input.dataset.ambEnabled);layer.enabled=input.checked;input.closest('.sound-layer-card').classList.toggle('disabled',!input.checked);this.ctx.save();if(this.ctx.engine.ambiences.active?.id===preset.id)try{await this.ctx.engine.ambiences.toggleLayer(layer.id,input.checked);}catch(e){toast(e.message,true);}});
    $$('[data-amb-pad]',root).forEach(button=>button.onclick=()=>{this.ctx.engine.oneShot(state.audioAssets.find(a=>a.id===button.dataset.ambPad),.8,{owner:{presetId:preset.id}}).catch(e=>toast(e.message,true));button.classList.add('fired');setTimeout(()=>button.classList.remove('fired'),500);});
    $$('[data-remove-pad]',root).forEach(button=>button.onclick=()=>{preset.pads=preset.pads.filter(id=>id!==button.dataset.removePad);this.ctx.commit();});$('#addAmbiencePad',root).onclick=()=>this.addPad(preset);
    this.update();
  }
  update(){
    if(!this.root?.isConnected||!$('#ambienceStatus',this.root))return;
    const bus=this.ctx.engine.ambiences,preset=this.selected(),active=bus.active?.id===preset?.id;
    $('#ambienceStatus',this.root).textContent=active?(bus.paused?'Ambiente pausado':`Em execução · ${bus.tracks.size} camadas · ${bus.jobs.size} ocasionais${bus.ownsMusic?' · trilha musical':''}`):bus.active?`Tocando: ${bus.active.name}`:'Pronto para tocar';
    $('#playAmbience',this.root).innerHTML=icon(active&&!bus.paused?'stop':'play')+(active&&!bus.paused?' Encerrar ambiente':active?' Retomar ambiente':' Ativar ambiente');
    $$('[data-amb-now]',this.root).forEach(el=>{const id=el.dataset.ambNow,track=active?(bus.tracks.get(id)||[...this.ctx.engine.effects].find(t=>!t.disposed&&t.owner?.presetId===preset.id&&t.owner?.layerId===id)):null;el.textContent=track?`${bus.paused?'Pausado':'Tocando'}: ${track.assetName||this.ctx.state().audioAssets.find(a=>a.id===track.assetId)?.name||track.name}`:active&&bus.jobs.has(id)?'Aguardando o próximo som':'Pronta para tocar';el.title=el.textContent;});
    $$('[data-amb-next]',this.root).forEach(b=>{const sequence=active?bus.sequences.get(b.dataset.ambNext):null;b.disabled=!sequence||bus.paused||!!sequence.loading;});
  }
  musicPanel(preset,state){
    const music=preset.music,source=music?.playlistId?state.playlists.find(p=>p.id===music.playlistId):state.audioAssets.find(a=>a.id===music?.assetId);
    return `<section class="ambient-music"><span class="ambient-music-art">${icon('music')}</span><div><span class="section-eyebrow">TRILHA MUSICAL DO LUGAR</span><h3>${esc(source?.name||'Adicione jazz, suspense ou a música deste lugar')}</h3><p>Começa com o ambiente. Aceita faixas e playlists, incluindo YouTube.</p>${music?`<label class="sound-layer-volume"><input data-amb-music-volume type="range" min="0" max="100" value="${Math.round((music.volume??1)*100)}" aria-label="Volume da trilha musical do ambiente"><output data-amb-music-value>${Math.round((music.volume??1)*100)}%</output></label>`:''}</div><button class="btn outline small" id="editAmbienceMusic">${icon(music?'sliders':'plus')} ${music?'Configurar':'Escolher trilha'}</button></section>`;
  }
  editMusic(preset){
    const state=this.ctx.state(),music=preset.music||{},selected=music.playlistId?'playlist:'+music.playlistId:music.assetId?'asset:'+music.assetId:'';
    openForm({title:`Trilha musical · ${preset.name}`,body:`<p class="dialog-description">A música começa ao ativar este lugar, junto das conversas e dos demais sons. A trilha usa o canal de música da mesa.</p><label class="field"><span>Faixa ou playlist</span><select name="source">${option('','Sem trilha vinculada',!selected)}<optgroup label="Playlists da biblioteca">${state.playlists.map(p=>option('playlist:'+p.id,p.name,selected==='playlist:'+p.id)).join('')}</optgroup><optgroup label="Faixas, YouTube e Spotify">${state.audioAssets.filter(a=>a.kind==='music'||['youtube','spotify'].includes(a.provider)).map(a=>option('asset:'+a.id,a.name+(a.provider==='youtube'?' · YouTube':a.provider==='spotify'?' · Spotify':''),selected==='asset:'+a.id)).join('')}</optgroup></select></label>${field('Volume da trilha (%)','volume',Math.round((music.volume??.65)*100),'type="number" min="0" max="100" required')}<div class="form-grid">${field('Fade de entrada (s)','fadeIn',music.fadeIn??state.settings.musicFadeIn,'type="number" min="0" max="30" step="0.1" required')}${field('Fade de saída (s)','fadeOut',music.fadeOut??state.settings.musicFadeOut,'type="number" min="0" max="30" step="0.1" required')}</div><label class="check-field"><input type="checkbox" name="loop" ${music.loop!==false?'checked':''}><span>Repetir a faixa individual enquanto o ambiente estiver ativo</span></label><p class="form-hint">O modo aleatório é o da playlist na biblioteca. Ao encerrar o ambiente, sua trilha sai em fade. Uma música iniciada separadamente continua sob seu controle. O YouTube usa o player visível da mesa. Spotify aplica fades pelo volume do player oficial.</p>`,onSubmit:form=>{
      const source=String(form.get('source'));if(source){const [type,...parts]=source.split(':');preset.music={mode:'play',loop:form.has('loop'),[type==='playlist'?'playlistId':'assetId']:parts.join(':'),volume:Number(form.get('volume'))/100,fadeIn:Number(form.get('fadeIn')),fadeOut:Number(form.get('fadeOut'))};}else delete preset.music;
      this.ctx.commit();if(this.ctx.engine.ambiences.active?.id===preset.id)this.ctx.engine.ambiences.apply(preset).catch(e=>toast(e.message,true));
    }});
  }
  edit(preset=null){openForm({title:preset?'Editar ambiente':'Novo ambiente',body:field('Nome','name',preset?.name||'','required maxlength="120" placeholder="Floresta à noite, taverna, laboratório…"')+field('Descrição','description',preset?.description||'','maxlength="350"')+'<div class="form-grid">'+field('Fade in do ambiente (s)','fadeIn',preset?.fadeIn??2,'type="number" min="0" max="30" step="0.1" required')+field('Fade out do ambiente (s)','fadeOut',preset?.fadeOut??2,'type="number" min="0" max="30" step="0.1" required')+'</div>'+(preset?'<button type="button" class="btn danger full" id="deleteAmbience">Excluir ambiente salvo</button>':''),onReady:root=>$('#deleteAmbience',root)?.addEventListener('click',()=>confirmAction('Excluir ambiente?',`O preset “${preset.name}” será excluído. Os arquivos de áudio continuam na biblioteca.`,()=>{if(this.ctx.engine.ambiences.active?.id===preset.id)this.ctx.engine.ambiences.stop(0);this.ctx.state().ambiences=this.ctx.state().ambiences.filter(a=>a.id!==preset.id);this.selectedId=null;this.ctx.commit();})),onSubmit:form=>{const name=String(form.get('name')).trim();if(!name)throw new Error('Informe um nome.');const values={name,description:String(form.get('description')).trim(),fadeIn:Number(form.get('fadeIn')),fadeOut:Number(form.get('fadeOut'))};if(preset)Object.assign(preset,values);else{const p={id:uid('ambience'),...values,layers:[],pads:[]};this.ctx.state().ambiences.push(p);this.selectedId=p.id;}this.ctx.commit();if(preset&&this.ctx.engine.ambiences.active?.id===preset.id)this.ctx.engine.ambiences.apply(preset).catch(e=>toast(e.message,true));}});}
  editLayer(preset,layer=null,preferPlaylist=false){
    const state=this.ctx.state(),assets=state.audioAssets.filter(a=>!['youtube','spotify'].includes(a.provider)),playlists=state.playlists.filter(p=>!p.assetIds.some(id=>['youtube','spotify'].includes(state.audioAssets.find(a=>a.id===id)?.provider)));
    if(preferPlaylist&&!playlists.length){toast('Crie uma playlist de arquivos na biblioteca. Para playlists com YouTube, use a trilha musical do lugar.',true);return;}
    const source=layer?.playlistId?'playlist:'+layer.playlistId:layer?.assetId?'asset:'+layer.assetId:preferPlaylist?'playlist:'+playlists[0].id:'asset:'+assets[0]?.id;
    openForm({title:layer?'Editar camada do ambiente':preferPlaylist?'Playlist do ambiente':'Nova camada de ambiente',body:field('Nome da camada','name',layer?.name||'','required maxlength="100" placeholder="Conversas no café…"')+`<label class="field"><span>Arquivo ou playlist</span><select name="source" id="ambientSource"><optgroup label="Playlists de arquivos">${playlists.map(p=>option('playlist:'+p.id,p.name+' · '+p.assetIds.length+' faixas',source==='playlist:'+p.id)).join('')}</optgroup><optgroup label="Arquivos da biblioteca">${assets.map(a=>option('asset:'+a.id,a.name,source==='asset:'+a.id)).join('')}</optgroup></select></label><div class="form-grid"><label class="field"><span>Comportamento</span><select name="mode" id="ambientMode">${[['loop','Contínuo (loop ou playlist)'],['random','Ocasional, com intervalos']].map(([v,l])=>option(v,l,v===(layer?.mode||'loop'))).join('')}</select></label>${field('Volume (%)','volume',Math.round((layer?.volume??.5)*100),'type="number" min="0" max="100" required')}</div>${fadeFields(layer,'Vazio herda os fades do arquivo ou ambiente. No modo ocasional, aplica a cada som; em loop, ao ativar/desligar a camada. O crossfade da playlist continua separado.')}<section id="ambientPlaylistOptions"><label class="check-field"><input type="checkbox" name="shuffle" ${(layer?.shuffle??true)?'checked':''}><span>Escolher as faixas aleatoriamente, sem repetir até completar a playlist</span></label><div id="ambientPlaylistFade">${field('Crossfade entre as faixas (s)','crossfade',layer?.crossfade??state.settings.crossfade,'type="number" min="0" max="30" step="0.1" required')}</div></section><div class="form-grid" id="randomIntervals">${field('Intervalo mínimo (s)','minInterval',layer?.minInterval??15,'type="number" min="0.1" max="3600" step="0.1" required')}${field('Intervalo máximo (s)','maxInterval',layer?.maxInterval??45,'type="number" min="0.1" max="3600" step="0.1" required')}</div><p class="form-hint">Contínuo: a próxima faixa entra com crossfade. Ocasional: sorteia um intervalo depois que o som termina. Combine várias playlists para criar conversas, pássaros ou ruídos variados. Playlists com YouTube entram pela trilha musical do lugar.</p>${layer?'<button type="button" class="btn danger full" id="deleteAmbLayer">Remover camada do ambiente</button>':''}`,onReady:root=>{
      const update=()=>{const playlist=$('#ambientSource',root).value.startsWith('playlist:'),random=$('#ambientMode',root).value==='random';$('#randomIntervals',root).hidden=!random;$$('input',$('#randomIntervals',root)).forEach(i=>i.disabled=!random);$('#ambientPlaylistOptions',root).hidden=!playlist;$$('input',$('#ambientPlaylistOptions',root)).forEach(i=>i.disabled=!playlist);$('#ambientPlaylistFade',root).hidden=random;$$('input',$('#ambientPlaylistFade',root)).forEach(i=>i.disabled=!playlist||random);const name=$('[name="name"]',root);if(!name.value){const [type,...id]=$('#ambientSource',root).value.split(':');name.value=(type==='playlist'?state.playlists:assets).find(a=>a.id===id.join(':'))?.name.slice(0,100)||'';}};
      $('#ambientMode',root).onchange=update;$('#ambientSource',root).onchange=update;update();$('#deleteAmbLayer',root)?.addEventListener('click',()=>{preset.layers=preset.layers.filter(l=>l!==layer);$('#appDialog').close();this.ctx.commit();if(this.ctx.engine.ambiences.active?.id===preset.id)this.ctx.engine.ambiences.apply(preset).catch(e=>toast(e.message,true));});
    },onSubmit:form=>{
      const name=String(form.get('name')).trim(),mode=form.get('mode'),min=Number(form.get('minInterval')),max=Number(form.get('maxInterval')),[type,...id]=String(form.get('source')).split(':');if(!name)throw new Error('Informe um nome.');if(mode==='random'&&max<min)throw new Error('O intervalo máximo deve ser maior ou igual ao mínimo.');
      const playlist=type==='playlist',value={id:layer?.id||uid('amb-layer'),name,[playlist?'playlistId':'assetId']:id.join(':'),mode,volume:Number(form.get('volume'))/100,enabled:layer?.enabled!==false,...readFades(form),...(playlist?{shuffle:form.has('shuffle'),...(mode==='loop'?{crossfade:Number(form.get('crossfade'))}:{})}:{}),...(mode==='random'?{minInterval:min,maxInterval:max}:{})};
      if(layer){const i=preset.layers.indexOf(layer);preset.layers[i]=value;}else preset.layers.push(value);this.ctx.commit();if(this.ctx.engine.ambiences.active?.id===preset.id)this.ctx.engine.ambiences.apply(preset).catch(e=>toast(e.message,true));
    }});
  }
  addPad(preset){const assets=this.ctx.state().audioAssets.filter(a=>!['youtube','spotify'].includes(a.provider)&&!preset.pads.includes(a.id));if(!assets.length){toast('Todos os arquivos disponíveis já estão neste painel. Envie mais áudios na biblioteca.');return;}openForm({title:'Adicionar disparo manual',body:'<label class="field"><span>Efeito da biblioteca</span><select name="assetId">'+assets.map(a=>option(a.id,a.name)).join('')+'</select></label>',submit:'Adicionar efeito',onSubmit:form=>{preset.pads.push(form.get('assetId'));this.ctx.commit();}});}
}
